export const products = raw.map((p) => {
  const fallbackImage = placeholderImage(p.id + p.name, p.category)
  return {
    ...p,
    image: p.image || fallbackImage,
    images: p.images && p.images.length > 0 ? p.images : [fallbackImage, placeholderImage(p.id + p.name + '2', p.category)],
  }
})

export const getProductBySlug = (slug) => products.find((p) => p.slug === slug)

export const getRelatedProducts = (product, limit = 4) =>
  products
    .filter((p) => p.id !== product.id && p.category === product.category)
    .slice(0, limit)

export const getFeaturedProducts = () => products.filter((p) => p.featured)

export const brands = [...new Set(products.map((p) => p.brand))].sort()

export const priceBounds = products.reduce(
  (acc, p) => ({
    min: Math.min(acc.min, p.price),
    max: Math.max(acc.max, p.price),
  }),
  { min: Infinity, max: 0 },
)
